import { z } from "zod";

export const campaignTypeSchema = z.enum(["TEMPLATE", "CONCRETE"]);
export const campaignStatusSchema = z.enum([
  "DRAFT", "PUBLISHED", "SCHEDULED", "PENDING_START", "ACTIVE", "PAUSED", "COMPLETED", "FAILED",
]);

const campaignDefinitionSchema = z.object({
  name: z.string().trim().min(1).max(200),
  type: campaignTypeSchema,
  emailTemplateId: z.string().min(1),
  pageId: z.string().min(1),
  mailSendingProfileId: z.string().min(1),
  targetGroupId: z.string().min(1).nullable(),
  targetTimezone: z.string().trim().min(1),
  autoCompleteAfterDays: z.number().int().positive().nullable().default(20),
}).superRefine((value, ctx) => {
  if (value.type === "TEMPLATE" && value.targetGroupId !== null) {
    ctx.addIssue({ code: "custom", path: ["targetGroupId"], message: "Templates cannot select a target group" });
  }
  if (value.type === "CONCRETE" && value.targetGroupId === null) {
    ctx.addIssue({ code: "custom", path: ["targetGroupId"], message: "Concrete campaigns require a target group" });
  }
});

export const ListCampaignsSchema = z.object({
  type: campaignTypeSchema.optional(),
  status: campaignStatusSchema.optional(),
  search: z.string().trim().optional(),
  limit: z.number().int().min(1).max(100).default(50),
  offset: z.number().int().min(0).default(0),
});
export const CampaignIdSchema = z.object({ id: z.string().min(1) });
export const CreateCampaignSchema = campaignDefinitionSchema;
export const UpdateCampaignSchema = z.object({ id: z.string().min(1), data: campaignDefinitionSchema });
export const CloneCampaignSchema = z.object({
  id: z.string().min(1),
  name: z.string().trim().min(1).max(200),
  type: campaignTypeSchema,
  targetGroupId: z.string().min(1).nullable(),
}).superRefine((value, ctx) => {
  if (value.type === "TEMPLATE" && value.targetGroupId !== null) ctx.addIssue({ code: "custom", path: ["targetGroupId"], message: "Templates cannot select a target group" });
  if (value.type === "CONCRETE" && value.targetGroupId === null) ctx.addIssue({ code: "custom", path: ["targetGroupId"], message: "Concrete campaigns require a target group" });
});

export const deliveryModeSchema = z.enum(["BLAST", "DRIP", "BATCH"]);
const scheduleDefinitionSchema = z.object({
  name: z.string().trim().min(1).max(200),
  type: z.enum(["ONE_TIME", "RECURRING"]),
  sourceCampaignIds: z.array(z.string().min(1)).min(1),
  targetGroupId: z.string().min(1).nullable(),
  targetTimezone: z.string().trim().min(1),
  startsAt: z.coerce.date(),
  frequency: z.enum(["WEEKLY", "MONTHLY", "QUARTERLY", "HALF_YEARLY", "YEARLY"]).nullable().default(null),
  localTimeMinutes: z.number().int().min(0).max(1439).nullable().default(null),
  weekday: z.number().int().min(0).max(6).nullable().default(null),
  dayOfMonth: z.number().int().min(1).max(31).nullable().default(null),
  month: z.number().int().min(1).max(12).nullable().default(null),
  selectionStrategy: z.enum(["DECK", "RANDOM"]).nullable().default(null),
  shuffleDeck: z.boolean().default(false),
  deliveryMode: deliveryModeSchema,
  dripEmailsPerMinute: z.number().int().positive().nullable().default(null),
  batchSize: z.number().int().positive().nullable().default(null),
  batchIntervalMinutes: z.number().int().positive().nullable().default(null),
  maxCampaigns: z.number().int().positive().nullable().default(null),
  endsAt: z.coerce.date().nullable().default(null),
  autoCompleteAfterDays: z.number().int().positive().nullable().default(20),
}).superRefine((value, ctx) => {
  if (value.type === "ONE_TIME" && value.sourceCampaignIds.length !== 1) ctx.addIssue({ code: "custom", path: ["sourceCampaignIds"], message: "One-time schedules require exactly one source" });
  if (value.type === "RECURRING" && (!value.frequency || !value.selectionStrategy)) ctx.addIssue({ code: "custom", path: ["frequency"], message: "Recurring schedules require frequency and strategy" });
  if (value.deliveryMode === "DRIP" && !value.dripEmailsPerMinute) ctx.addIssue({ code: "custom", path: ["dripEmailsPerMinute"], message: "Drip rate is required" });
  if (value.deliveryMode === "BATCH" && (!value.batchSize || !value.batchIntervalMinutes)) ctx.addIssue({ code: "custom", path: ["batchSize"], message: "Batch size and interval are required" });
  if (value.endsAt && value.endsAt <= value.startsAt) ctx.addIssue({ code: "custom", path: ["endsAt"], message: "End date must follow start date" });
});

export const ListSchedulesSchema = z.object({ limit: z.number().int().min(1).max(100).default(50), offset: z.number().int().min(0).default(0) });
export const CreateScheduleSchema = scheduleDefinitionSchema;
export const UpdateScheduleSchema = z.object({ id: z.string().min(1), data: scheduleDefinitionSchema });
export const MaterializeOccurrenceSchema = z.object({ scheduleId: z.string().min(1), sourceCampaignId: z.string().min(1), occurrenceAt: z.coerce.date() });

export type CampaignDefinitionInput = z.infer<typeof CreateCampaignSchema>;
export type ScheduleDefinitionInput = z.infer<typeof CreateScheduleSchema>;

import { createHash } from "node:crypto";
import type { Prisma, PrismaClient } from "@prisma/client";
import type { CampaignDefinitionInput, ScheduleDefinitionInput } from "./validations";

type Tx = Prisma.TransactionClient;

const campaignInclude = {
  emailTemplate: { select: { id: true, name: true, visibility: true, status: true } },
  page: { select: { id: true, name: true, visibility: true, status: true } },
  mailSendingProfile: { select: { id: true, name: true, visibility: true } },
  targetGroup: { select: { id: true, name: true, visibility: true, status: true, _count: { select: { users: true } } } },
} as const;

export class CampaignRepository {
  constructor(private readonly db: PrismaClient) {}

  listCampaigns(organizationId: string, input: { type?: "TEMPLATE" | "CONCRETE"; status?: Prisma.EnumCampaignStatusFilter["equals"]; search?: string; limit: number; offset: number }) {
    const where: Prisma.CampaignWhereInput = {
      organizationId,
      type: input.type,
      status: input.status,
      name: input.search ? { contains: input.search, mode: "insensitive" } : undefined,
      scheduleId: null,
    };
    return Promise.all([
      this.db.campaign.findMany({ where, include: campaignInclude, orderBy: { updatedAt: "desc" }, take: input.limit, skip: input.offset }),
      this.db.campaign.count({ where }),
    ]).then(([rows, total]) => ({ rows, total }));
  }

  getCampaign(id: string, organizationId: string) {
    return this.db.campaign.findFirst({ where: { id, organizationId }, include: { ...campaignInclude, schedule: true } });
  }

  async createCampaign(organizationId: string, createdById: string, data: CampaignDefinitionInput) {
    await this.assertCatalogResources(this.db, organizationId, data);
    return this.db.campaign.create({ data: { ...data, organizationId, createdById }, include: campaignInclude });
  }

  async updateCampaign(id: string, organizationId: string, data: CampaignDefinitionInput) {
    await this.assertCatalogResources(this.db, organizationId, data);
    const existing = await this.db.campaign.findFirst({ where: { id, organizationId, scheduleId: null } });
    if (!existing) throw new Error("Campaign not found");
    if (!["DRAFT", "PUBLISHED"].includes(existing.status)) throw new Error("Started campaigns cannot be edited");
    return this.db.campaign.update({ where: { id }, data, include: campaignInclude });
  }

  async publish(id: string, organizationId: string) {
    const result = await this.db.campaign.updateMany({ where: { id, organizationId, status: "DRAFT", scheduleId: null }, data: { status: "PUBLISHED" } });
    if (!result.count) throw new Error("Only a draft campaign can be published");
    return this.getCampaign(id, organizationId);
  }

  async cloneCampaign(id: string, organizationId: string, createdById: string, data: { name: string; type: "TEMPLATE" | "CONCRETE"; targetGroupId: string | null }) {
    const source = await this.db.campaign.findFirst({ where: { id, organizationId, scheduleId: null } });
    if (!source) throw new Error("Campaign not found");
    const definition = {
      name: data.name,
      type: data.type,
      emailTemplateId: source.emailTemplateId!,
      pageId: source.pageId!,
      mailSendingProfileId: source.mailSendingProfileId!,
      targetGroupId: data.type === "TEMPLATE" ? null : data.targetGroupId,
      targetTimezone: source.targetTimezone,
      autoCompleteAfterDays: source.autoCompleteAfterDays,
    } satisfies CampaignDefinitionInput;
    await this.assertCatalogResources(this.db, organizationId, definition);
    return this.db.campaign.create({ data: { ...definition, organizationId, createdById, sourceCampaignId: source.id }, include: campaignInclude });
  }

  listSchedules(organizationId: string, limit: number, offset: number) {
    return Promise.all([
      this.db.schedule.findMany({ where: { organizationId }, include: { sources: { include: { campaign: { select: { id: true, name: true, type: true } } }, orderBy: { position: "asc" } }, targetGroup: { select: { id: true, name: true, _count: { select: { users: true } } } }, _count: { select: { campaigns: true } } }, orderBy: { startsAt: "desc" }, take: limit, skip: offset }),
      this.db.schedule.count({ where: { organizationId } }),
    ]).then(([rows, total]) => ({ rows, total }));
  }

  getSchedule(id: string, organizationId: string) {
    return this.db.schedule.findFirst({ where: { id, organizationId }, include: { sources: { orderBy: { position: "asc" }, include: { campaign: true } }, campaigns: { orderBy: { occurrenceAt: "desc" } }, targetGroup: true } });
  }

  async createSchedule(organizationId: string, createdById: string, data: ScheduleDefinitionInput) {
    return this.db.$transaction(async (tx) => {
      const sources = await this.validateScheduleSources(tx, organizationId, data);
      const fingerprint = this.fingerprint(data);
      const collision = await tx.schedule.findFirst({ where: { organizationId, collisionFingerprint: fingerprint, status: { not: "CANCELLED" } }, select: { id: true, name: true } });
      const { sourceCampaignIds, ...scheduleData } = data;
      const schedule = await tx.schedule.create({ data: { ...scheduleData, organizationId, createdById, status: "SCHEDULED", nextOccurrenceAt: data.startsAt, collisionFingerprint: fingerprint, targetGroupId: this.resolveScheduleTarget(data, sources), sources: { create: sourceCampaignIds.map((campaignId, position) => ({ campaignId, position })) } }, include: { sources: true } });
      return { schedule, collisionWarning: collision ? { scheduleId: collision.id, scheduleName: collision.name } : null };
    });
  }

  async updateSchedule(id: string, organizationId: string, data: ScheduleDefinitionInput) {
    return this.db.$transaction(async (tx) => {
      const schedule = await tx.schedule.findFirst({ where: { id, organizationId } });
      if (!schedule) throw new Error("Schedule not found");
      if (["COMPLETED", "CANCELLED"].includes(schedule.status)) throw new Error("Terminal schedules cannot be edited");
      const locked = await tx.campaign.count({ where: { scheduleId: id, status: { in: ["PENDING_START", "ACTIVE", "PAUSED"] } } });
      if (locked) throw new Error("Schedule fields are locked while a campaign is pending or active");
      const sources = await this.validateScheduleSources(tx, organizationId, data);
      const { sourceCampaignIds, ...scheduleData } = data;
      await tx.scheduleSource.deleteMany({ where: { scheduleId: id } });
      await tx.campaign.deleteMany({ where: { scheduleId: id, status: "SCHEDULED" } });
      return tx.schedule.update({ where: { id }, data: { ...scheduleData, targetGroupId: this.resolveScheduleTarget(data, sources), nextOccurrenceAt: data.startsAt, collisionFingerprint: this.fingerprint(data), sources: { create: sourceCampaignIds.map((campaignId, position) => ({ campaignId, position })) } }, include: { sources: true } });
    });
  }

  async cancelSchedule(id: string, organizationId: string) {
    return this.db.$transaction(async (tx) => {
      const schedule = await tx.schedule.findFirst({ where: { id, organizationId } });
      if (!schedule) throw new Error("Schedule not found");
      await tx.campaign.updateMany({ where: { scheduleId: id, status: { in: ["SCHEDULED", "PENDING_START", "ACTIVE", "PAUSED"] } }, data: { status: "COMPLETED" } });
      return tx.schedule.update({ where: { id }, data: { status: "CANCELLED", cancelledAt: new Date(), nextOccurrenceAt: null } });
    });
  }

  async duplicateSchedule(id: string, organizationId: string, createdById: string) {
    const source = await this.getSchedule(id, organizationId);
    if (!source) throw new Error("Schedule not found");
    const data = {
      name: `${source.name} copy`, type: source.type, sourceCampaignIds: source.sources.map((item) => item.campaignId), targetGroupId: source.targetGroupId,
      targetTimezone: source.targetTimezone, startsAt: source.startsAt, frequency: source.frequency, localTimeMinutes: source.localTimeMinutes,
      weekday: source.weekday, dayOfMonth: source.dayOfMonth, month: source.month, selectionStrategy: source.selectionStrategy,
      shuffleDeck: source.shuffleDeck, deliveryMode: source.deliveryMode, dripEmailsPerMinute: source.dripEmailsPerMinute,
      batchSize: source.batchSize, batchIntervalMinutes: source.batchIntervalMinutes, maxCampaigns: source.maxCampaigns,
      endsAt: source.endsAt, autoCompleteAfterDays: source.autoCompleteAfterDays,
    } satisfies ScheduleDefinitionInput;
    return this.createSchedule(organizationId, createdById, data);
  }

  async materializeOccurrence(scheduleId: string, sourceCampaignId: string, occurrenceAt: Date, organizationId: string, createdById: string) {
    return this.db.$transaction(async (tx) => {
      const schedule = await tx.schedule.findFirst({ where: { id: scheduleId, organizationId, status: { in: ["SCHEDULED", "RUNNING"] } }, include: { sources: true } });
      if (!schedule || !schedule.sources.some((source) => source.campaignId === sourceCampaignId)) throw new Error("Valid schedule source not found");
      const source = await tx.campaign.findFirst({ where: { id: sourceCampaignId, organizationId }, include: { emailTemplate: { include: { files: { include: { file: true } } } }, page: true, mailSendingProfile: true, targetGroup: { include: { users: true } } } });
      if (!source?.emailTemplate || !source.page || !source.mailSendingProfile) throw new Error("Schedule source is broken");
      const targetGroup = source.type === "CONCRETE" ? source.targetGroup : await tx.targetGroup.findFirst({ where: { id: schedule.targetGroupId ?? "", organizationId, visibility: "CATALOG" }, include: { users: true } });
      if (!targetGroup) throw new Error("Target group is unavailable");
      const run = await tx.campaign.create({ data: { organizationId, createdById, name: `${source.name} — ${occurrenceAt.toISOString()}`, type: "CONCRETE", status: "SCHEDULED", targetTimezone: schedule.targetTimezone, autoCompleteAfterDays: schedule.autoCompleteAfterDays, sourceCampaignId: source.id, scheduleId: schedule.id, occurrenceAt } });

      const shadowFiles = new Map<string, string>();
      for (const link of source.emailTemplate.files) {
        const file = link.file;
        const shadow = await tx.file.create({ data: { storedObjectId: file.storedObjectId, name: file.name, size: file.size, format: file.format, purpose: file.purpose, visibility: "SHADOW", organizationId, uploadedById: file.uploadedById, shadowCampaignId: run.id, sourceFileId: file.id } });
        shadowFiles.set(file.id, shadow.id);
      }
      const email = source.emailTemplate;
      const shadowEmail = await tx.emailTemplate.create({ data: { name: email.name, tags: email.tags, html: email.html, design: email.design as Prisma.InputJsonValue, organizationId, createdById: email.createdById, status: email.status, trackingPixel: email.trackingPixel, visibility: "SHADOW", contentRevision: email.contentRevision, shadowCampaignId: run.id, sourceTemplateId: email.id, files: { create: email.files.map((link) => ({ fileId: shadowFiles.get(link.fileId)! })) } } });
      const shadowPage = await this.clonePage(tx, source.page.id, organizationId, run.id);
      const profile = source.mailSendingProfile;
      const shadowProfile = await tx.mailSendingProfile.create({ data: { organizationId, name: profile.name, providerType: profile.providerType, fromName: profile.fromName, fromEmail: profile.fromEmail, replyToEmail: profile.replyToEmail, headers: profile.headers ?? undefined, providerConfig: profile.providerConfig, isDefault: false, visibility: "SHADOW", shadowCampaignId: run.id, sourceSendingProfileId: profile.id } });
      const seen = new Set<string>();
      const users = targetGroup.users.flatMap((user) => { const normalizedEmail = user.email.trim().toLowerCase(); if (seen.has(normalizedEmail)) return []; seen.add(normalizedEmail); return [{ email: user.email.trim(), normalizedEmail, firstName: user.firstName, lastName: user.lastName, position: user.position }]; });
      const shadowGroup = await tx.targetGroup.create({ data: { name: targetGroup.name, status: targetGroup.status, organizationId, createdById: targetGroup.createdById, visibility: "SHADOW", shadowCampaignId: run.id, sourceTargetGroupId: targetGroup.id, users: { create: users } } });
      return tx.campaign.update({ where: { id: run.id }, data: { emailTemplateId: shadowEmail.id, pageId: shadowPage.id, mailSendingProfileId: shadowProfile.id, targetGroupId: shadowGroup.id }, include: campaignInclude });
    });
  }

  private async clonePage(tx: Tx, sourceId: string, organizationId: string, campaignId: string): Promise<{ id: string }> {
    const source = await tx.page.findFirst({ where: { id: sourceId, organizationId }, include: { redirectPage: true } });
    if (!source) throw new Error("Page is unavailable");
    const redirect = source.redirectPage ? await this.clonePage(tx, source.redirectPage.id, organizationId, campaignId) : null;
    return tx.page.create({ data: { name: source.name, type: source.type, html: source.html, design: source.design ?? undefined, status: source.status, captureData: source.captureData, redirectUrl: source.redirectUrl, redirectPageId: redirect?.id, contentType: source.contentType, organizationId, createdById: source.createdById, visibility: "SHADOW", contentRevision: source.contentRevision, shadowCampaignId: campaignId, sourcePageId: source.id }, select: { id: true } });
  }

  private async assertCatalogResources(client: PrismaClient | Tx, organizationId: string, data: Pick<CampaignDefinitionInput, "emailTemplateId" | "pageId" | "mailSendingProfileId" | "targetGroupId" | "type">) {
    const [email, page, profile, group] = await Promise.all([
      client.emailTemplate.findFirst({ where: { id: data.emailTemplateId, organizationId, visibility: "CATALOG", status: "ACTIVE" }, select: { id: true } }),
      client.page.findFirst({ where: { id: data.pageId, organizationId, visibility: "CATALOG", status: "ACTIVE" }, select: { id: true } }),
      client.mailSendingProfile.findFirst({ where: { id: data.mailSendingProfileId, organizationId, visibility: "CATALOG" }, select: { id: true } }),
      data.targetGroupId ? client.targetGroup.findFirst({ where: { id: data.targetGroupId, organizationId, visibility: "CATALOG", status: "ACTIVE" }, select: { id: true } }) : null,
    ]);
    if (!email || !page || !profile || (data.type === "CONCRETE" && !group)) throw new Error("Campaign resources must be active catalog resources in the organization");
  }

  private async validateScheduleSources(tx: Tx, organizationId: string, data: ScheduleDefinitionInput) {
    const sources = await tx.campaign.findMany({ where: { id: { in: data.sourceCampaignIds }, organizationId, status: "PUBLISHED", scheduleId: null } });
    if (sources.length !== new Set(data.sourceCampaignIds).size) throw new Error("One or more schedule sources are unavailable");
    if (data.type === "RECURRING" && sources.some((source) => source.type !== "TEMPLATE")) throw new Error("Repeating schedules only accept templates");
    if (data.type === "ONE_TIME" && sources[0]?.type === "TEMPLATE" && !data.targetGroupId) throw new Error("Template schedules require a target group");
    if (data.targetGroupId && !(await tx.targetGroup.findFirst({ where: { id: data.targetGroupId, organizationId, visibility: "CATALOG", status: "ACTIVE" } }))) throw new Error("Target group is unavailable");
    return sources;
  }

  private resolveScheduleTarget(data: ScheduleDefinitionInput, sources: Array<{ type: string; targetGroupId: string | null }>) {
    return sources[0]?.type === "CONCRETE" ? sources[0].targetGroupId : data.targetGroupId;
  }

  private fingerprint(data: ScheduleDefinitionInput) {
    const stable = JSON.stringify({ ...data, sourceCampaignIds: [...data.sourceCampaignIds].sort(), startsAt: data.startsAt.toISOString(), endsAt: data.endsAt?.toISOString() ?? null });
    return createHash("sha256").update(stable).digest("hex");
  }
}

