import { beforeAll, beforeEach, describe, expect, it } from "vitest";
import type { PrismaClient } from "@prisma/client";
import { CampaignRepository } from "../../src/campaign/campaign.repository";
import { EmailTemplateRepository } from "../../src/email-template/repositories/email-template.repository";
import { getFactories, getPrisma } from "../setup";

describe("CampaignRepository", () => {
  let db: PrismaClient;
  let repo: CampaignRepository;
  let organizationId: string;
  let userId: string;
  let refs: { emailTemplateId: string; pageId: string; mailSendingProfileId: string; targetGroupId: string };

  beforeAll(() => { db = getPrisma(); repo = new CampaignRepository(db); });
  beforeEach(async () => {
    const factories = getFactories();
    const [user, organization] = await Promise.all([factories.user.createOne(), factories.organization.createOne()]);
    userId = user.id; organizationId = organization.id;
    const storedObject = await db.storedObject.create({ data: { remoteId: `test/${crypto.randomUUID()}`, size: 10, format: "text/plain", organizationId } });
    const file = await db.file.create({ data: { storedObjectId: storedObject.id, name: "attachment.txt", size: 10, format: "text/plain", organizationId, uploadedById: userId } });
    const [email, page, profile, group] = await Promise.all([
      db.emailTemplate.create({ data: { name: "Email", tags: [], html: "<p>Hello</p>", design: {}, organizationId, createdById: userId, status: "ACTIVE", files: { create: { fileId: file.id } } } }),
      db.page.create({ data: { name: "Landing", html: "<h1>Hi</h1>", organizationId, createdById: userId, status: "ACTIVE" } }),
      db.mailSendingProfile.create({ data: { organizationId, name: "SMTP", providerType: "SMTP", fromName: "Sender", fromEmail: "sender@example.test", providerConfig: {} } }),
      db.targetGroup.create({ data: { name: "Targets", organizationId, createdById: userId, status: "ACTIVE", users: { create: [{ email: " User@Example.test ", normalizedEmail: "user@example.test", firstName: "A", lastName: "B" }] } } }),
    ]);
    refs = { emailTemplateId: email.id, pageId: page.id, mailSendingProfileId: profile.id, targetGroupId: group.id };
  });

  it("rejects cross-organization campaign resources", async () => {
    const other = await getFactories().organization.createOne();
    await expect(repo.createCampaign(other.id, userId, { name: "Invalid", type: "CONCRETE", ...refs, targetTimezone: "UTC", autoCompleteAfterDays: 20 })).rejects.toThrow(/organization/);
  });

  it("hides shadow templates from catalog repositories", async () => {
    await db.emailTemplate.create({ data: { name: "Shadow", tags: [], html: "", design: {}, organizationId, createdById: userId, visibility: "SHADOW", status: "ACTIVE" } });
    const result = await new EmailTemplateRepository(db).findByOrganizationId(organizationId, { limit: 50, offset: 0 });
    expect(result.rows.map((row) => row.name)).toEqual(["Email"]);
  });

  it("materializes relational shadows and shares immutable attachment objects", async () => {
    const source = await repo.createCampaign(organizationId, userId, { name: "Template", type: "TEMPLATE", emailTemplateId: refs.emailTemplateId, pageId: refs.pageId, mailSendingProfileId: refs.mailSendingProfileId, targetGroupId: null, targetTimezone: "UTC", autoCompleteAfterDays: 20 });
    await repo.publish(source.id, organizationId);
    const { schedule } = await repo.createSchedule(organizationId, userId, { name: "One time", type: "ONE_TIME", sourceCampaignIds: [source.id], targetGroupId: refs.targetGroupId, targetTimezone: "UTC", startsAt: new Date("2030-01-01T12:00:00Z"), frequency: null, localTimeMinutes: null, weekday: null, dayOfMonth: null, month: null, selectionStrategy: null, shuffleDeck: false, deliveryMode: "BLAST", dripEmailsPerMinute: null, batchSize: null, batchIntervalMinutes: null, maxCampaigns: null, endsAt: null, autoCompleteAfterDays: 20 });
    const run = await repo.materializeOccurrence(schedule.id, source.id, new Date("2030-01-01T12:00:00Z"), organizationId, userId);

    expect(run.status).toBe("SCHEDULED");
    expect(run.emailTemplate?.visibility).toBe("SHADOW");
    expect(run.targetGroup?.visibility).toBe("SHADOW");
    const files = await db.file.findMany({ where: { shadowCampaignId: run.id } });
    const original = await db.emailTemplateFile.findFirstOrThrow({ where: { emailTemplateId: refs.emailTemplateId }, include: { file: true } });
    expect(files).toHaveLength(1);
    expect(files[0].storedObjectId).toBe(original.file.storedObjectId);
  });
});

