const MAX_BYTES = 2 * 1024 * 1024;
const MAX_WIDTH = 4096;
const MAX_HEIGHT = 16384;

function imageDimensions(buffer: Buffer, format: string): { width: number; height: number } {
  if (format === "image/png" && buffer.length >= 24 && buffer.subarray(0, 8).equals(Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]))) {
    return { width: buffer.readUInt32BE(16), height: buffer.readUInt32BE(20) };
  }
  if (format === "image/webp" && buffer.length >= 30 && buffer.toString("ascii", 0, 4) === "RIFF" && buffer.toString("ascii", 8, 12) === "WEBP" && buffer.toString("ascii", 12, 16) === "VP8X") {
    return { width: 1 + buffer.readUIntLE(24, 3), height: 1 + buffer.readUIntLE(27, 3) };
  }
  throw new Error("Preview bytes do not match the declared PNG/WebP format");
}

export class CatalogPreviewService {
  constructor(private readonly db: PrismaClient, private readonly r2: R2Client) {}

  async upload(input: UploadCatalogPreviewInput) {
    const buffer = Buffer.from(input.body, "base64");
    if (!buffer.length || buffer.length > MAX_BYTES) throw new Error("Preview must be between 1 byte and 2 MiB");
    const dimensions = imageDimensions(buffer, input.format);
    if (dimensions.width < 1 || dimensions.height < 1 || dimensions.width > MAX_WIDTH || dimensions.height > MAX_HEIGHT) throw new Error("Preview dimensions are outside the allowed range");

    const revision = input.resourceType === "EMAIL_TEMPLATE"
      ? await this.db.emailTemplate.findFirst({ where: { id: input.resourceId, organizationId: input.organizationId, visibility: "CATALOG" }, select: { contentRevision: true } })
      : await this.db.page.findFirst({ where: { id: input.resourceId, organizationId: input.organizationId, visibility: "CATALOG" }, select: { contentRevision: true } });
    if (!revision) throw new Error("Catalog resource not found");
    if (revision.contentRevision !== input.sourceRevision) throw new Error("Preview is stale; regenerate it from the latest revision");

    const extension = input.format === "image/png" ? "png" : "webp";
    const remoteId = `catalog-previews/${input.organizationId}/${input.resourceId}/${input.sourceRevision}-${randomUUID()}.${extension}`;
    await this.r2.uploadObject(remoteId, buffer, input.format);

    try {
      const result = await this.db.$transaction(async (tx) => {
        const old = await tx.catalogPreview.findFirst({ where: input.resourceType === "EMAIL_TEMPLATE" ? { emailTemplateId: input.resourceId } : { pageId: input.resourceId }, include: { file: { include: { storedObject: true } } } });
        const storedObject = await tx.storedObject.create({ data: { remoteId, size: buffer.length, format: input.format, organizationId: input.organizationId } });
        const file = await tx.file.create({ data: { storedObjectId: storedObject.id, name: `preview-${input.resourceId}.${extension}`, size: buffer.length, format: input.format, purpose: "CATALOG_PREVIEW", organizationId: input.organizationId, uploadedById: input.uploadedById } });
        const preview = await tx.catalogPreview.upsert({
          where: input.resourceType === "EMAIL_TEMPLATE" ? { emailTemplateId: input.resourceId } : { pageId: input.resourceId },
          create: { organizationId: input.organizationId, emailTemplateId: input.resourceType === "EMAIL_TEMPLATE" ? input.resourceId : null, pageId: input.resourceType === "PAGE" ? input.resourceId : null, fileId: file.id, sourceRevision: input.sourceRevision, status: "READY" },
          update: { fileId: file.id, sourceRevision: input.sourceRevision, status: "READY", failureReason: null },
        });
        if (old?.file) {
          await tx.file.delete({ where: { id: old.file.id } });
          const count = await tx.file.count({ where: { storedObjectId: old.file.storedObjectId } });
          if (!count) await tx.storedObject.delete({ where: { id: old.file.storedObjectId } });
        }
        return { preview, oldRemoteId: old?.file?.storedObject.remoteId };
      });

