          },
        },
      },
      select: fileSelect,
    });
    return flattenStoredObject(row);
  }

  async delete(id: string): Promise<{ deleted: boolean; orphanedRemoteId?: string }> {
    const row = await this.db.file.findFirst({
      where: { id, visibility: "CATALOG" },
      select: { storedObjectId: true, storedObject: { select: { remoteId: true } } },
    });
    if (!row) return { deleted: false };

